use std::{fs, io::{self, Read, Write}, path::{Path, PathBuf}, process::Command, thread, time::Duration};
use std::os::unix::io::AsRawFd;

const BOARDS: [&str; 4] = ["pico2", "pimoroni_tiny2350", "waveshare_rp2350_usb_a", "waveshare_rp2350_zero"];
fn err(s: impl Into<String>) -> io::Error { io::Error::new(io::ErrorKind::InvalidInput, s.into()) }
fn arg(a: &[String], name: &str) -> Option<String> { a.iter().position(|x| x == name).and_then(|i| a.get(i + 1)).cloned() }
fn root() -> PathBuf { Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap().to_path_buf() }
fn firmware(a: &[String], board: &str) -> io::Result<PathBuf> {
    if !BOARDS.contains(&board) { return Err(err(format!("unknown board {board}; choose {}", BOARDS.join(", ")))); }
    let name = format!("usbr34ker.{board}.uf2");
    let mut roots = Vec::new();
    if let Some(x) = arg(a, "--firmware-dir") { roots.push(PathBuf::from(x)); }
    roots.push(root().join("goat/usbr34ker/firmware"));
    if let Ok(exe) = std::env::current_exe() { if let Some(p) = exe.parent() { roots.push(p.join("firmware")); roots.push(p.join("../lib/usbr34ker/firmware")); } }
    roots.into_iter().map(|p| p.join(&name)).find(|p| p.is_file()).ok_or_else(|| err(format!("missing bundled firmware: {name}")))
}
fn mounts() -> Vec<PathBuf> { ["/Volumes/RPI-RP2", "/media/RPI-RP2", "/run/media/RPI-RP2"].into_iter().map(PathBuf::from).filter(|p| p.is_dir()).collect() }
fn ports() -> Vec<PathBuf> { let mut out=Vec::new(); if let Ok(es)=fs::read_dir("/dev"){for e in es.flatten(){let n=e.file_name().to_string_lossy().into_owned();if n.contains("usbmodem")||n.contains("usbserial")||n.starts_with("ttyACM")||n.starts_with("ttyUSB"){out.push(e.path())}}}out.sort();out }
fn configure(path: &Path, baud: u32) -> io::Result<()> { let flag=if cfg!(target_os="macos"){"-f"}else{"-F"};let s=Command::new("stty").args([flag,path.to_str().unwrap_or_default(),&baud.to_string(),"cs8","-cstopb","-parenb","raw","-echo"]).status()?;if s.success(){Ok(())}else{Err(err("failed to configure CDC UART"))} }
fn terminal(path: &Path, baud: u32) -> io::Result<()> { configure(path,baud)?;let mut port=fs::OpenOptions::new().read(true).write(true).open(path)?;let s=Command::new("stty").args(["raw","-echo"]).status()?;if !s.success(){return Err(err("failed to put terminal in raw mode"))}println!("goat: CDC UART {baud} baud on {}; press Ctrl-] to exit",path.display());let stdin=io::stdin();let mut f=[libc::pollfd{fd:stdin.as_raw_fd(),events:libc::POLLIN,revents:0},libc::pollfd{fd:port.as_raw_fd(),events:libc::POLLIN,revents:0}];let mut b=[0u8;4096];loop{let n=unsafe{libc::poll(f.as_mut_ptr(),2,50)};if n<0{break}if f[1].revents&libc::POLLIN!=0{let n=port.read(&mut b)?;if n>0{io::stdout().write_all(&b[..n])?;io::stdout().flush()?}}if f[0].revents&libc::POLLIN!=0{let n=stdin.lock().read(&mut b)?;if b[..n].contains(&0x1d){break}if n>0{port.write_all(&b[..n])?}}}let _=Command::new("stty").arg("sane").status();Ok(()) }
pub fn guided(a: &[String]) -> io::Result<()> { println!("GOAT / usbr34ker guided setup\nConnect the RP2350 board while holding BOOTSEL.");let board=arg(a,"--board").unwrap_or_else(||{print!("Board [{}]: ",BOARDS[0]);let _=io::stdout().flush();let mut s=String::new();let _=io::stdin().read_line(&mut s);let s=s.trim().to_owned();if s.is_empty(){BOARDS[0].into()}else{s}});let src=firmware(a,&board)?;let mount=arg(a,"--mount").map(PathBuf::from).or_else(||mounts().into_iter().next()).ok_or_else(||err("RP2 boot volume not found; hold BOOTSEL or pass --mount"))?;let dst=mount.join(src.file_name().unwrap());fs::copy(&src,&dst)?;println!("goat: flashed {board} ({} bytes); waiting for reboot",fs::metadata(&src)?.len());thread::sleep(Duration::from_secs(2));if a.iter().any(|x|x=="--no-terminal"){return Ok(())}let port=arg(a,"--port").map(PathBuf::from).or_else(||{for _ in 0..20{if let Some(p)=ports().into_iter().next(){return Some(p)}thread::sleep(Duration::from_millis(250))}None}).ok_or_else(||err("CDC UART not detected; pass --port /dev/cu.usbmodemXXXX"))?;terminal(&port,arg(a,"--baud").and_then(|x|x.parse().ok()).unwrap_or(115200)) }
pub fn list(a: &[String]) -> io::Result<()> { println!("goat: usbr34ker boards: {}",BOARDS.join(", "));for b in BOARDS{println!("  {b}: {}",firmware(a,b).map(|x|x.display().to_string()).unwrap_or_else(|_|"MISSING".into()))}println!("goat: serial ports: {:?}",ports());println!("goat: RP2 boot volumes: {:?}",mounts());Ok(()) }
pub fn flash(a: &[String]) -> io::Result<()> {let b=arg(a,"--board").ok_or_else(||err("--board is required"))?;let src=firmware(a,&b)?;let m=arg(a,"--mount").map(PathBuf::from).or_else(||mounts().into_iter().next()).ok_or_else(||err("RP2 boot volume not found; hold BOOTSEL or pass --mount"))?;fs::copy(&src,m.join(src.file_name().unwrap()))?;println!("goat: flashed {b}");Ok(())}
